// ParseStratumQueryRpcIds converts a comma-separated string to a slice of StratumQueryRpcId enum values
// Returns an error if any value is invalid
func ParseStratumQueryRpcIds(s string) ([]StratumQueryRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]StratumQueryRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseStratumQueryRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

